import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = in.nextInt();
        int k = in.nextInt();
        int[] poly = new int[10];
        for (int i = 0; i < k; i++) {
            poly[in.nextInt()] = 1;
        }

        int[] res = new int[]{1};
        int exp = n / 2;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = multiply(res, poly, MOD);
            }
            poly = multiply(poly, poly, MOD);
            exp >>= 1;
        }

        long sum = 0;
        for (int val : res) {
            sum = (sum + (long)val * val) % MOD;
        }
        out.println(sum);
        out.close();
    }

    static int[] multiply(int[] a, int[] b, int mod) {
        int lenA = a.length, lenB = b.length;
        int need = lenA + lenB - 1;
        int size = 1;
        while (size < need) size <<= 1;

        double[] ar = new double[size];
        double[] ai = new double[size];
        double[] br = new double[size];
        double[] bi = new double[size];

        for (int i = 0; i < lenA; i++) {
            long val = ((long)a[i] % mod + mod) % mod;
            ar[i] = val & 0x7fff;
            ai[i] = val >>> 15;
        }
        for (int i = 0; i < lenB; i++) {
            long val = ((long)b[i] % mod + mod) % mod;
            br[i] = val & 0x7fff;
            bi[i] = val >>> 15;
        }

        transform(ar, ai, false);
        transform(br, bi, false);

        double[] cr = new double[size];
        double[] ci = new double[size];
        double[] dr = new double[size];
        double[] di = new double[size];

        double factor = 0.25 / size;
        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;

            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            cr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            ci[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            dr[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            di[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        transform(cr, ci, true);
        transform(dr, di, true);

        int[] result = new int[need];
        for (int i = 0; i < need; i++) {
            long p1 = Math.round(cr[i]);
            long p2 = Math.round(dr[i]);
            long p3 = Math.round(ci[i]);
            result[i] = (int)((p1 + ((p2 % mod) << 15) + ((p3 % mod) << 30)) % mod);
        }
        return result;
    }

    static void transform(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int bits = 32 - Integer.numberOfLeadingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i) >>> (32 - bits);
            if (i < j) {
                double t = re[i]; re[i] = re[j]; re[j] = t;
                t = im[i]; im[i] = im[j]; im[j] = t;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosTable = new double[half];
            double[] sinTable = new double[half];
            double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
            for (int i = 0; i < half; i++) {
                cosTable[i] = Math.cos(i * angle);
                sinTable[i] = Math.sin(i * angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double cr = cosTable[j];
                    double ci = sinTable[j];
                    double ur = re[i + j];
                    double ui = im[i + j];
                    double vr = re[i + j + half] * cr - im[i + j + half] * ci;
                    double vi = re[i + j + half] * ci + im[i + j + half] * cr;

                    re[i + j] = ur + vr;
                    im[i + j] = ui + vi;
                    re[i + j + half] = ur - vr;
                    im[i + j + half] = ui - vi;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream input;
        private final byte[] buffer = new byte[1024];
        private int index, total;

        public InputReader(InputStream input) { this.input = input; }

        private int get() {
            if (total == -1) throw new RuntimeException();
            if (index >= total) {
                index = 0;
                try { total = input.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (total <= 0) return -1;
            }
            return buffer[index++] & 0xff;
        }

        public int nextInt() {
            int c;
            while ((c = get()) <= ' ') if (c == -1) throw new RuntimeException();
            int sign = 1;
            if (c == '-') { sign = -1; c = get(); }
            int num = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                num = num * 10 + c - '0';
                c = get();
            } while (c > ' ');
            return num * sign;
        }
    }
}
